window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0217b95f6c6cad5c"]={"versions": [{"id": "FIG-0217b95f6c6cad5c", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung eines funktionalen Teilabschnitts innerhalb des AUTOSAR E2E-Protokolls (Profile 6). Das Diagramm spezifiziert den detaillierten Teilschritt „Write CRC“ innerhalb der Schutz- und Weiterleitungsfunktionen <code>E2E_P06Protect()</code> und <code>E2E_P06Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionskontext (Aufrufer):</strong> <code>E2E_P06Protect()</code> und <code>E2E_P06Forward()</code> (dargestellt als aufrufende Aktionen/Kontexte mit Sub-Aktivitätssymbol).</li>\n<li><strong>Aktion:</strong> <code>Copy 2-byte local variable CRC on bytes Data[Offset+0...Offset+1] using big Endian order</code>.</li>\n<li><strong>Datenstrukturen & Variablen:</strong></li>\n<li><code>CRC</code>: Lokale Variable (2 Byte groß / 16 Bit).</li>\n<li><code>Data[]</code>: Byte-Array zur Aufnahme der serialisierten Nutz- und Steuerdaten.</li>\n<li><code>Offset</code>: Konfigurationsparameter/Index-Offset zur Lokalisierung der CRC-Position im Datenpuffer.</li>\n<li><strong>Knotenelemente:</strong> Initialknoten (schwarzer Punkt) und Endknoten (Aktivitätsendknoten/Bullseye).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eintritt über den Initialknoten beim Start des Einzelschritts „Write CRC“ innerhalb von <code>E2E_P06Protect()</code> bzw. <code>E2E_P06Forward()</code>.</li>\n<li>Ausführung der Aktion: Der zuvor berechnete 2-Byte-Wert der lokalen Variable <code>CRC</code> wird in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in das Pufferarray auf die Positionen <code>Data[Offset + 0]</code> und <code>Data[Offset + 1]</code> kopiert.</li>\n<li>Kontrollflussübergang direkt zum Endknoten zur Beendigung des Schreibschritts.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert das verbindliche Verhalten für [PRS_E2E_00428]. Entwickler müssen sicherstellen, dass die 16-Bit-Prüfsumme platformunabhängig strikt in Big-Endian-Serialisierung (Network Byte Order) in das Ziel-Array <code>Data</code> geschrieben wird, unabhängig von der nativen Byte-Reihenfolge der Host-CPU. Der Schreibvorgang überschreibt exakt zwei aufeinanderfolgende Bytes beginnend beim konfigurierten <code>Offset</code>.</p>"}, {"id": "FIG-dfc0fbcf25511c66", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung eines funktionalen Teilabschnitts innerhalb des AUTOSAR E2E-Protokolls (Profile 6). Das Diagramm spezifiziert den detaillierten Teilschritt „Write CRC“ innerhalb der Schutz- und Weiterleitungsfunktionen <code>E2E_P06Protect()</code> und <code>E2E_P06Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionskontext (Aufrufer):</strong> <code>E2E_P06Protect()</code> und <code>E2E_P06Forward()</code> (dargestellt als aufrufende Aktionen/Kontexte mit Sub-Aktivitätssymbol).</li>\n<li><strong>Aktion:</strong> <code>Copy 2-byte local variable CRC on bytes Data[Offset+0...Offset+1] using big Endian order</code>.</li>\n<li><strong>Datenstrukturen & Variablen:</strong></li>\n<li><code>CRC</code>: Lokale Variable (2 Byte groß / 16 Bit).</li>\n<li><code>Data[]</code>: Byte-Array zur Aufnahme der serialisierten Nutz- und Steuerdaten.</li>\n<li><code>Offset</code>: Konfigurationsparameter/Index-Offset zur Lokalisierung der CRC-Position im Datenpuffer.</li>\n<li><strong>Knotenelemente:</strong> Initialknoten (schwarzer Punkt) und Endknoten (Aktivitätsendknoten/Bullseye).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eintritt über den Initialknoten beim Start des Einzelschritts „Write CRC“ innerhalb von <code>E2E_P06Protect()</code> bzw. <code>E2E_P06Forward()</code>.</li>\n<li>Ausführung der Aktion: Der zuvor berechnete 2-Byte-Wert der lokalen Variable <code>CRC</code> wird in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in das Pufferarray auf die Positionen <code>Data[Offset + 0]</code> und <code>Data[Offset + 1]</code> kopiert.</li>\n<li>Kontrollflussübergang direkt zum Endknoten zur Beendigung des Schreibschritts.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert das verbindliche Verhalten für [PRS_E2E_00428]. Entwickler müssen sicherstellen, dass die 16-Bit-Prüfsumme platformunabhängig strikt in Big-Endian-Serialisierung (Network Byte Order) in das Ziel-Array <code>Data</code> geschrieben wird, unabhängig von der nativen Byte-Reihenfolge der Host-CPU. Der Schreibvorgang überschreibt exakt zwei aufeinanderfolgende Bytes beginnend beim konfigurierten <code>Offset</code>.</p>"}], "trans": [{"from": "FIG-0217b95f6c6cad5c", "to": "FIG-dfc0fbcf25511c66", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
